# find ORFs on both strands, all 6 frames
seq = ''
with open('region.fasta') as f:
    for line in f:
        line=line.strip()
        if not line.startswith('>') and line:
            seq += line.upper()

def revcomp(s):
    return s.translate(str.maketrans('ACGT','TGCA'))[::-1]

comp = revcomp(seq)

def longest_orfs(s, strand):
    orfs=[]
    n=len(s)
    for frame in range(3):
        i=frame
        start=None
        while i < n-2:
            cod=s[i:i+3]
            if start is None:
                if cod=='ATG':
                    start=i
            else:
                if cod in ('TAA','TAG','TGA'):
                    length=i+3-start
                    if length>=150:
                        orfs.append((start,i+3,length,strand,frame))
                    start=None
                # if hit stop without start, ignore
            i+=3
        # trailing ORF to end without stop
        if start is not None:
            length=n-start
            if length>=150:
                orfs.append((start,n,length,strand,frame))
    return orfs

allorfs = longest_orfs(seq,'+') + longest_orfs(comp,'-')
allorfs.sort(key=lambda x:-x[2])
print("ORFs >=150 nt (50 aa):")
for start,end,length,strand,frame in allorfs:
    if strand=='+':
        cs,ce = start+1,end
    else:
        cs,ce = len(seq)-end+1, len(seq)-start
    print(f"strand {strand} frame {frame}  nt {cs}-{ce}  len {length}  aa {length//3-1}  coord(+):{start+1}-{end}")
"}

